const DISC=[null,["Автокросс", "Cross Country по глухому бездорожью: прыжки, заборы, грязь. Нужны клиренс, ход подвески и оффроуд-шины."],["Вышибала", "Один выбирает точку А, второй — Б. Дальше свобода: шоссе или напрямик. Решают знание карты и резина."],["Первопроходец", "Зоны Первопроходца: ворота и финиш по пересечёнке. Места — по запасу секунд на таймере."],["Заезд стоков на гору", "Подъём на самую высокую вершину на стоке. Решают полный привод, момент и вес."],["Грунтовые гонки спринт", "Ралли от точки до точки по гравию и асфальту. Нужен раллийный зацеп и управляемый занос."],["Гонка на выносливость круг", "Грунтовое кольцо с износом шин и повреждениями. Одна ошибка — и подвеска убита."],["Тогэ спринт-дуэли", "Парные заезды на серпантине по круговой системе. Чистый асфальт, зацеп и короткие передачи."],["Шоссе круг", "Кольцо на асфальте: прижим, слики, траектории и точки торможения."],["Заезд стоков шоссе спринт", "Линейный спринт на стоковых машинах. Важны старт без пробуксовки и эффективность стока."],["Уличная гонка", "Ночные заезды с трафиком и слепыми чекпоинтами. Нужна быстрая и манёвренная машина."],["Радар + Скоростной участок", "Максимум км/ч на радаре + лучшая средняя на скоростном участке. Результаты суммируются."],["Прыжок + Максимальная скорость", "Дальность прыжка с трамплина в метрах + максималка на самом длинном прямике."],["Толкучка", "Силовое противостояние бампер в бампер на площадке EventLab: вес, момент, полный привод."],["Дрифт", "Дрифт-зоны: очки за угол и скорость скольжения. Нужна дрифт-настройка."],["Драг", "Прямая, 3 попытки, идёт лучшее время. Важны лаунч, давление шин и длинная первая передача."],["Царь горы", "Бой на выживание, 3 жизни: таранить и сбрасывать соперников. Побеждает последний."]];
const DG=['Бездорожье','Грунт','Шоссе','Уникальные'],DGI=i=>i<=4?0:i<=6?1:i<=10?2:3,cids=s=>s?String(s).split(',').map(Number):[],RAR={c:'Common',r:'Rare',e:'Epic',l:'Legendary',f:'Forza Edition',t:'Treasure',b:'Barn Find'},priceF=p=>p?(p>=1000?+(p/1000).toFixed(2)+' млн':p+' тыс.'):'—',wofCar=()=>CARS.find(c=>c[1]+' '+c[2]==S.wofc),dnames=s=>cids(s).map(i=>DISC[i][0]).join(' · ');
function carsView(){const f=cf,U=i=>[...new Set(CARS.map(c=>c[i]))].filter(v=>v!=='').sort(),sel=(k,i,t)=>`<select data-cf="${k}"><option value="">${t}</option>${U(i).map(v=>`<option ${f[k]==v?'selected':''}>${e(v)}</option>`).join('')}</select>`,num=(k,t)=>`<input data-cf="${k}" type="number" placeholder="${t}" value="${e(f[k]||'')}" style="width:90px">`,
ra=`<select data-cf="ra"><option value="">Редкость</option>${Object.entries(RAR).map(([k,v])=>`<option value="${k}" ${f.ra==k?'selected':''}>${v}</option>`).join('')}</select>`,
ds=`<select data-cf="ds"><option value="">Подходит для…</option>${DISC.slice(1).map((d,i)=>`<option value="${i+1}" ${f.ds==i+1?'selected':''}>${i+1}. ${e(d[0])}</option>`).join('')}</select>`,
so=[['4','PI'],['1','Год'],['0','Марка'],['9','Цена'],['10','Потенциал']],k=+f.so,
R=CARS.filter(c=>(!f.q||(c[0]+' '+c[2]).toLowerCase().includes(f.q.toLowerCase()))&&(!f.cl||c[5]==f.cl)&&(!f.co||c[6]==f.co)&&(!f.ty||c[3]==f.ty)&&(!f.dt||c[7]==f.dt)&&(!f.ra||c[8]==f.ra)&&(!f.ds||cids(c[11]).includes(+f.ds)||cids(c[12]).includes(+f.ds))&&(!f.p0||c[4]>=+f.p0)&&(!f.p1||c[4]<=+f.p1)&&(!f.y0||c[1]>=+f.y0)&&(!f.y1||c[1]<=+f.y1)).sort((a,b)=>(a[k]>b[k]?1:a[k]<b[k]?-1:0)*f.dir);
return`<h2>Список машин</h2><div class="card row"><input data-cf="q" placeholder="Поиск" value="${e(f.q||'')}">${sel('cl',5,'Класс')}${sel('dt',7,'Привод')}${ra}${ds}${sel('co',6,'Страна')}${sel('ty',3,'Тип')}${num('p0','PI от')}${num('p1','PI до')}${num('y0','Год от')}${num('y1','Год до')}<select data-cf="so">${so.map(([v,t])=>`<option value="${v}"${f.so==v?' selected':''}>${t}</option>`).join('')}</select><select data-cf="dir"><option value="-1"${f.dir=='-1'?' selected':''}>↓</option><option value="1"${f.dir=='1'?' selected':''}>↑</option></select></div><div class="card tbl"><table><tr><th>Марка</th><th>Год</th><th>Модель</th><th>Тип</th><th>PI</th><th>Класс</th><th>Привод</th><th>Редкость</th><th>Цена, CR</th><th>Лучшие дисциплины</th><th>Потенциал</th><th>Страна</th><th>🎡</th></tr>${R.slice(0,300).map(c=>`<tr><td>${e(c[0])}</td><td>${c[1]}</td><td>${e(c[2])}</td><td>${e(c[3])}</td><td><b class="pi">${c[4]}</b></td><td><span class="cl cl-${c[5]}">${c[5]}</span></td><td>${c[7]||'—'}</td><td>${RAR[c[8]]||'—'}</td><td>${priceF(c[9])}</td><td style="white-space:normal;min-width:240px;text-align:left;font-size:12px" title="Запасные: ${e(dnames(c[12]))}">${e(dnames(c[11]))||'—'}</td><td>${c[10]?'★'.repeat(c[10])+'☆'.repeat(5-c[10]):'—'}</td><td>${CF[c[6]]?flag(CF[c[6]]):''}${e(c[6])}</td><td><button class="btn" data-a="wcar" data-k="${CARS.indexOf(c)}" title="В Колесо Фортуны">🎡</button></td></tr>`).join('')}</table><p class="mut">Показано ${Math.min(300,R.length)} из ${R.length}. Привод, редкость и цена — по открытым спискам (у части новых машин пусто). «Лучшие дисциплины» и «Потенциал» — предварительная оценка по типу машины, не проверенный рейтинг; запасные варианты видно при наведении.</p></div>`}

